export function createRootLookupMap(): Map<string, string> {
  const DIACRITICS = /[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06DC\u06DF-\u06E4\u06E7\u06E8\u06EA-\u06ED]/g;
  const map = new Map<string, string>();
  for (const [word, root] of Object.entries(ROOT_LOOKUP)) {
    map.set(word.replace(DIACRITICS, ''), root);
  }
  return map;
}
